schemaSql:
-- Extend existing shauger_profiles table with student attributes if not present
ALTER TABLE public.shauger_profiles 
  ADD COLUMN IF NOT EXISTS major text DEFAULT 'ميكانيكا',
  ADD COLUMN IF NOT EXISTS dark_mode boolean DEFAULT false,
  ADD COLUMN IF NOT EXISTS notifications_enabled boolean DEFAULT true;

-- 1. Posts Table
CREATE TABLE IF NOT EXISTS public.shauger_posts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  post_type text NOT NULL CHECK (post_type IN ('جدول', 'محاضرة', 'فعالية', 'خبر')),
  title text NOT NULL,
  content text NOT NULL,
  target_major text NOT NULL DEFAULT 'الكل' CHECK (target_major IN ('الكل', 'ميكانيكا', 'تصنيع', 'مدنية', 'كهربا')),
  author_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

-- 2. Post Attachments Table
CREATE TABLE IF NOT EXISTS public.shauger_post_attachments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  post_id uuid NOT NULL REFERENCES public.shauger_posts(id) ON DELETE CASCADE,
  file_name text NOT NULL,
  file_type text NOT NULL CHECK (file_type IN ('image', 'video', 'document')),
  file_url text NOT NULL,
  file_size_bytes bigint DEFAULT 0,
  created_at timestamptz DEFAULT now()
);

-- 3. Post Emoji Reactions Table
CREATE TABLE IF NOT EXISTS public.shauger_post_reactions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  post_id uuid NOT NULL REFERENCES public.shauger_posts(id) ON DELETE CASCADE,
  customer_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE,
  emoji text NOT NULL CHECK (emoji IN ('👍', '❤️', '😂', '😮', '😢', '🙏')),
  created_at timestamptz DEFAULT now(),
  UNIQUE (post_id, customer_id)
);

-- 4. Local Downloads Track Table
CREATE TABLE IF NOT EXISTS public.shauger_local_downloads (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE,
  attachment_id uuid NOT NULL REFERENCES public.shauger_post_attachments(id) ON DELETE CASCADE,
  local_path text,
  downloaded_at timestamptz DEFAULT now(),
  UNIQUE (customer_id, attachment_id)
);

-- 5. User Settings Table
CREATE TABLE IF NOT EXISTS public.shauger_user_settings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE UNIQUE,
  dark_mode boolean NOT NULL DEFAULT false,
  push_notifications boolean NOT NULL DEFAULT true,
  updated_at timestamptz DEFAULT now()
);

-- Row Level Security Setup
ALTER TABLE public.shauger_posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.shauger_post_attachments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.shauger_post_reactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.shauger_local_downloads ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.shauger_user_settings ENABLE ROW LEVEL SECURITY;

-- RLS Policies for shauger_posts
DROP POLICY IF EXISTS "Authenticated users can view posts" ON public.shauger_posts;
CREATE POLICY "Authenticated users can view posts" ON public.shauger_posts 
  FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Admins can manage posts" ON public.shauger_posts;
CREATE POLICY "Admins can manage posts" ON public.shauger_posts 
  FOR ALL TO authenticated 
  USING (public.shauger_is_admin()) 
  WITH CHECK (public.shauger_is_admin());

-- RLS Policies for shauger_post_attachments
DROP POLICY IF EXISTS "Authenticated users can view attachments" ON public.shauger_post_attachments;
CREATE POLICY "Authenticated users can view attachments" ON public.shauger_post_attachments 
  FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Admins can manage attachments" ON public.shauger_post_attachments;
CREATE POLICY "Admins can manage attachments" ON public.shauger_post_attachments 
  FOR ALL TO authenticated 
  USING (public.shauger_is_admin()) 
  WITH CHECK (public.shauger_is_admin());

-- RLS Policies for shauger_post_reactions
DROP POLICY IF EXISTS "Authenticated users can view reactions" ON public.shauger_post_reactions;
CREATE POLICY "Authenticated users can view reactions" ON public.shauger_post_reactions 
  FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Customers can insert their own reaction" ON public.shauger_post_reactions;
CREATE POLICY "Customers can insert their own reaction" ON public.shauger_post_reactions 
  FOR INSERT TO authenticated WITH CHECK (customer_id = auth.uid());

DROP POLICY IF EXISTS "Customers can update their own reaction" ON public.shauger_post_reactions;
CREATE POLICY "Customers can update their own reaction" ON public.shauger_post_reactions 
  FOR UPDATE TO authenticated USING (customer_id = auth.uid()) WITH CHECK (customer_id = auth.uid());

DROP POLICY IF EXISTS "Customers can delete their own reaction" ON public.shauger_post_reactions;
CREATE POLICY "Customers can delete their own reaction" ON public.shauger_post_reactions 
  FOR DELETE TO authenticated USING (customer_id = auth.uid());

DROP POLICY IF EXISTS "Admins can manage reactions" ON public.shauger_post_reactions;
CREATE POLICY "Admins can manage reactions" ON public.shauger_post_reactions 
  FOR ALL TO authenticated 
  USING (public.shauger_is_admin()) 
  WITH CHECK (public.shauger_is_admin());

-- RLS Policies for shauger_local_downloads
DROP POLICY IF EXISTS "Customers can view their downloads" ON public.shauger_local_downloads;
CREATE POLICY "Customers can view their downloads" ON public.shauger_local_downloads 
  FOR SELECT TO authenticated USING (customer_id = auth.uid());

DROP POLICY IF EXISTS "Customers can insert downloads" ON public.shauger_local_downloads;
CREATE POLICY "Customers can insert downloads" ON public.shauger_local_downloads 
  FOR INSERT TO authenticated WITH CHECK (customer_id = auth.uid());

DROP POLICY IF EXISTS "Customers can delete downloads" ON public.shauger_local_downloads;
CREATE POLICY "Customers can delete downloads" ON public.shauger_local_downloads 
  FOR DELETE TO authenticated USING (customer_id = auth.uid());

DROP POLICY IF EXISTS "Admins can manage downloads" ON public.shauger_local_downloads;
CREATE POLICY "Admins can manage downloads" ON public.shauger_local_downloads 
  FOR ALL TO authenticated 
  USING (public.shauger_is_admin()) 
  WITH CHECK (public.shauger_is_admin());

-- RLS Policies for shauger_user_settings
DROP POLICY IF EXISTS "Customers can manage settings" ON public.shauger_user_settings;
CREATE POLICY "Customers can manage settings" ON public.shauger_user_settings 
  FOR ALL TO authenticated 
  USING (customer_id = auth.uid()) 
  WITH CHECK (customer_id = auth.uid());

DROP POLICY IF EXISTS "Admins can manage user settings" ON public.shauger_user_settings;
CREATE POLICY "Admins can manage user settings" ON public.shauger_user_settings 
  FOR ALL TO authenticated 
  USING (public.shauger_is_admin()) 
  WITH CHECK (public.shauger_is_admin());

